import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a circular street with {n_houses} labeled houses, the mail carrier plans a delivery pattern for a single day under these rules: (i) no two adjacent houses receive mail on the same day, and (ii) there are never more than {max_no_mail_run} consecutive houses in a row that receive no mail on that day. If exactly {deliver_count} houses receive mail, how many distinct labeled delivery patterns are possible around the circle?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a circular version with exact-k ones and max run of zeros L,
# ensuring feasibility: 2k <= n <= k(L+1), k >= 1.
# Use retries to satisfy constraints.
for _ in range(1000):
    n = rng.randint(18, 60)  # big enough to be nontrivial
    L_max = min(8, n - 2)
    if L_max < 2:
        continue
    L = rng.randint(2, L_max)
    # Feasible k must satisfy ceil(n/(L+1)) <= k <= floor(n/2)
    lo_k = (n + (L + 1) - 1) // (L + 1)
    hi_k = n // 2
    if lo_k < 1:
        lo_k = 1
    if lo_k > hi_k:
        continue
    k = rng.randint(lo_k, hi_k)
    # Avoid trivial extreme selections with mild bias when range is wide.
    if hi_k - lo_k >= 4 and rng.random() < 0.5:
        k = rng.randint(lo_k + 1, hi_k - 1)
    return {
        'n_houses': n,
        'max_no_mail_run': L,
        'deliver_count': k
    }
# Fallback (feasible and moderately hard)
return {
    'n_houses': 37,
    'max_no_mail_run': 5,
    'deliver_count': 12
}

    def verifier(assign):
# Verify domain and compute the exact count via dynamic programming on the circle.
# Constraints: no adjacent ones; zero-run length <= L globally (including wrap-around);
# exactly k ones; houses are labeled (rotations are distinct).
try:
    n = int(assign.get('n_houses'))
    L = int(assign.get('max_no_mail_run'))
    k = int(assign.get('deliver_count'))
except Exception:
    # invalid types
    return (False, None)

# Basic validation
if n <= 0 or L <= 0 or k < 0:
    # invalid parameters
    return (False, None)
# We disallow k=0 to avoid degenerate corner where only all-zero pattern might qualify
if k == 0:
    return (False, None)
# Enforce computational hardness/feasibility window
lo_k = (n + (L + 1) - 1) // (L + 1)  # ceil(n/(L+1))
hi_k = n // 2
if lo_k < 1:
    lo_k = 1
if not (lo_k <= k <= hi_k):
    # infeasible request under the constraints
    return (False, None)
if L < 2:
    # keep it nontrivial (memory size >= 2) and avoid pathological simple alternation cases
    return (False, None)
if n < 12:
    # avoid very small instances
    return (False, None)

# Case A: b1 = 1. Then b_n must be 0 (to avoid adjacent ones across wrap),
# and the wrap zero-run cannot merge across boundary because of the 1 at position 1.
# DP maintains prev bit and current zero-run length z (consecutive zeros ending at current position), and ones count w.
# We process positions 2..n with a special constraint at position n: b_n must be 0.
def count_case_A(n, L, k):
    # dp_zero[z][w]: prev=0 and zero-run length z (>=1); dp_one[z][w]: prev=1 (z=0 always used)
    dp_zero = [[0]*(k+1) for _ in range(L+1)]
    dp_one  = [[0]*(k+1) for _ in range(L+1)]
    # initialize at position 1: prev=1, z=0, w=1
    dp_one[0][1] = 1
    # positions 2..n-1
    for pos in range(2, n):
        new_zero = [[0]*(k+1) for _ in range(L+1)]
        new_one  = [[0]*(k+1) for _ in range(L+1)]
        # transitions from prev=1 (b must be 0)
        for z in range(L+1):
            for w in range(k+1):
                cnt = dp_one[z][w]
                if cnt == 0:
                    continue
                # append 0: new prev=0, z'=1
                if 1 <= L:
                    new_zero[1][w] += cnt
        # transitions from prev=0
        for z in range(1, L+1):
            for w in range(k+1):
                cnt = dp_zero[z][w]
                if cnt == 0:
                    continue
                # append 0: z' = z+1 <= L
                if z + 1 <= L:
                    new_zero[z+1][w] += cnt
                # append 1: allowed, z'=0, prev=1, w+1
                if w + 1 <= k:
                    new_one[0][w+1] += cnt
        dp_zero, dp_one = new_zero, new_one
    # final position n: b_n must be 0
    final_zero = [[0]*(k+1) for _ in range(L+1)]
    # from prev=1: append 0 -> prev=0, z'=1
    for z in range(L+1):
        for w in range(k+1):
            cnt = dp_one[z][w]
            if cnt:
                if 1 <= L:
                    final_zero[1][w] += cnt
    # from prev=0: append 0 -> z' = z+1
    for z in range(1, L+1):
        for w in range(k+1):
            cnt = dp_zero[z][w]
            if cnt:
                if z + 1 <= L:
                    final_zero[z+1][w] += cnt
    # sum all with w==k
    ansA = sum(final_zero[z][k] for z in range(L+1))
    return ansA

# Case B: b1 = 0. We must track lead_z (initial zeros run until the first 1 appears),
# and at the end enforce z_end + lead_z <= L. Also track ones count.
def count_case_B(n, L, k):
    # dp_before[z]: still before first 1, prev=0, current zero-run z, ones count w=0.
    dp_before = [0]*(L+1)
    dp_before[1] = 1  # position 1 is zero
    # dp_after_prev0[lead][z][w], dp_after_prev1[lead][z][w]
    dp_after_prev0 = [[[0]*(k+1) for _ in range(L+1)] for __ in range(L+1)]
    dp_after_prev1 = [[[0]*(k+1) for _ in range(L+1)] for __ in range(L+1)]
    # iterate positions 2..n
    for pos in range(2, n+1):
        # next layers
        nb_before = [0]*(L+1)
        na_prev0 = [[[0]*(k+1) for _ in range(L+1)] for __ in range(L+1)]
        na_prev1 = [[[0]*(k+1) for _ in range(L+1)] for __ in range(L+1)]
        # transitions from before-first-1
        for z in range(1, L+1):
            cnt = dp_before[z]
            if cnt == 0:
                continue
            # append 0: stay before, z' = z+1
            if z + 1 <= L:
                nb_before[z+1] += cnt
            # append 1: start, lead = z, prev=1, z'=0, w=1
            if 1 <= k:
                na_prev1[z][0][1] += cnt
        # transitions from after-first-1
        for lead in range(1, L+1):
            # from prev=1: only append 0 -> prev0, z'=1
            for z in range(L+1):
                for w in range(k+1):
                    cnt = dp_after_prev1[lead][z][w]
                    if cnt == 0:
                        continue
                    if 1 <= L:
                        na_prev0[lead][1][w] += cnt
            # from prev=0
            for z in range(1, L+1):
                for w in range(k+1):
                    cnt = dp_after_prev0[lead][z][w]
                    if cnt == 0:
                        continue
                    # append 0: z' = z+1
                    if z + 1 <= L:
                        na_prev0[lead][z+1][w] += cnt
                    # append 1: z'=0, prev1, w+1
                    if w + 1 <= k:
                        na_prev1[lead][0][w+1] += cnt
        # update layers
        dp_before = nb_before
        dp_after_prev0 = na_prev0
        dp_after_prev1 = na_prev1
    # At pos=n, count those after-first-1 with w==k and wrap zero-run constraint: z_end + lead <= L.
    ansB = 0
    for lead in range(1, L+1):
        for z in range(L+1):
            if z + lead <= L:
                ansB += dp_after_prev0[lead][z][k]
                ansB += dp_after_prev1[lead][z][k]
    return ansB

ans = count_case_A(n, L, k) + count_case_B(n, L, k)

# Sanity: must be positive and reasonably nontrivial
if ans <= 0:
    return (False, None)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

